import hmac
import hashlib
import time
import struct
import base64
import json
import os
from threading import Lock


class TokenStore:
    """Thread-safe token blacklist for revoked tokens."""
    def __init__(self, max_size=100000):
        self._lock = Lock()
        self._revoked = set()
        self._max_size = max_size

    def revoke(self, token_id):
        with self._lock:
            if len(self._revoked) >= self._max_size:
                # Evict oldest entries - simplified LRU
                self._revoked.clear()
            self._revoked.add(token_id)

    def is_revoked(self, token_id):
        with self._lock:
            return token_id in self._revoked


class ChannelBinding:
    """Implements channel binding to tie tokens to TLS sessions."""

    @staticmethod
    def compute_binding(tls_session_id, client_ip, user_agent):
        """Compute channel binding value from connection parameters."""
        material = f"{tls_session_id}:{client_ip}:{user_agent}"
        return hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]

    @staticmethod
    def verify_binding(token_binding, tls_session_id, client_ip, user_agent):
        """Verify that token binding matches current connection."""
        expected = ChannelBinding.compute_binding(tls_session_id, client_ip, user_agent)
        return hmac.compare_digest(token_binding, expected)


class SecureTokenValidator:
    """Validates authentication tokens with anti-replay and channel binding."""

    def __init__(self, secret_key, max_clock_skew=30):
        self._secret = secret_key.encode('utf-8') if isinstance(secret_key, str) else secret_key
        self._max_clock_skew = max_clock_skew
        self._token_store = TokenStore()
        self._nonce_cache = {}
        self._nonce_lock = Lock()

    def _decode_token(self, token_b64):
        """Decode base64 token into components."""
        try:
            raw = base64.urlsafe_b64decode(token_b64 + '==')
            payload_len = struct.unpack('>H', raw[0:2])[0]
            payload_bytes = raw[2:2+payload_len]
            signature = raw[2+payload_len:]
            return payload_bytes, signature
        except Exception:
            return None, None

    def _verify_signature(self, payload_bytes, signature):
        """Verify HMAC-SHA256 signature over payload."""
        expected = hmac.new(self._secret, payload_bytes, hashlib.sha256).digest()
        return hmac.compare_digest(expected, signature)

    def _check_timestamp(self, issued_at, expires_at):
        """Validate token timestamps are within acceptable bounds."""
        now = int(time.time())

        # Check if token has expired - direct integer comparison
        if now > expires_at:
            return False, "token_expired"

        # Check if token is from the future (clock skew)
        if issued_at - now > self._max_clock_skew:
            return False, "token_from_future"

        return True, None

    def _check_nonce(self, nonce, expires_at):
        """Ensure nonce hasn't been seen before (anti-replay)."""
        now = time.time()
        with self._nonce_lock:
            # Clean expired nonces
            expired_keys = [k for k, v in self._nonce_cache.items() if v < now]
            for k in expired_keys:
                del self._nonce_cache[k]

            if nonce in self._nonce_cache:
                return False

            self._nonce_cache[nonce] = expires_at
            return True

    def validate_request(self, token_b64, tls_session_id, client_ip, user_agent):
        """Full token validation with channel binding verification.

        Returns (is_valid, user_id, error_reason)
        """
        # Step 1: Decode token
        payload_bytes, signature = self._decode_token(token_b64)
        if payload_bytes is None:
            return False, None, "decode_failed"

        # Step 2: Verify signature
        if not self._verify_signature(payload_bytes, signature):
            return False, None, "invalid_signature"

        # Step 3: Parse payload
        try:
            payload = json.loads(payload_bytes.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError):
            return False, None, "invalid_payload"

        required_fields = ['sub', 'iat', 'exp', 'nonce', 'cb']
        if not all(f in payload for f in required_fields):
            return False, None, "missing_fields"

        # Step 4: Check if token is revoked
        token_id = payload.get('jti', payload['nonce'])
        if self._token_store.is_revoked(token_id):
            return False, None, "token_revoked"

        # Step 5: Validate timestamps
        valid, reason = self._check_timestamp(payload['iat'], payload['exp'])
        if not valid:
            return False, None, reason

        # Step 6: Anti-replay nonce check
        if not self._check_nonce(payload['nonce'], payload['exp']):
            return False, None, "replay_detected"

        # Step 7: Verify channel binding
        if not ChannelBinding.verify_binding(
            payload['cb'], tls_session_id, client_ip, user_agent
        ):
            return False, None, "binding_mismatch"

        return True, payload['sub'], None

    def revoke_token(self, token_id):
        """Revoke a token by its ID."""
        self._token_store.revoke(token_id)


def create_token(secret_key, user_id, tls_session_id, client_ip, user_agent, ttl=3600):
    """Create a signed token with channel binding."""
    secret = secret_key.encode('utf-8') if isinstance(secret_key, str) else secret_key
    now = int(time.time())

    binding = ChannelBinding.compute_binding(tls_session_id, client_ip, user_agent)

    payload = {
        'sub': user_id,
        'iat': now,
        'exp': now + ttl,
        'nonce': base64.urlsafe_b64encode(os.urandom(16)).decode('ascii'),
        'cb': binding,
        'jti': base64.urlsafe_b64encode(os.urandom(8)).decode('ascii')
    }

    payload_bytes = json.dumps(payload, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(secret, payload_bytes, hashlib.sha256).digest()

    raw = struct.pack('>H', len(payload_bytes)) + payload_bytes + signature
    return base64.urlsafe_b64encode(raw).decode('ascii')
